'use strict';
let dailyBusy=false;
function dailyArticlesHTML(editions){const current=editions.map(e=>({...e,articles:e.articles.filter(a=>a.format===2)})).filter(e=>e.articles.length);return current.map(e=>`<section class="daily-edition"><h2>${esc(e.date)}</h2><div class="daily-grid">${e.articles.map(a=>`<article class="daily-article"><div class="daily-tickers">${a.tickers.map(t=>`<button data-ticker="${esc(t)}">${esc(t)}</button>`).join('')}<small>Source date ${esc(a.published)}</small></div><h3>${esc(a.title)}</h3><p class="daily-tldr">${esc(a.tldr)}</p><div class="daily-evidence">${a.evidence.map(e=>`<p><b>${esc(e.kind)} · ${esc(e.date||'date unconfirmed')}</b>${esc(e.fact)} ${researchLink(e.url,'Evidence ↗')}</p>`).join('')}</div><p><b>The connection · hypothesis</b> ${esc(a.why)}</p><p><b>Already priced in?</b> ${esc(a.pricedIn)}</p><p><b>What breaks the thesis</b> ${esc(a.invalidation)}</p><p><b>Risk / uncertainty</b> ${esc(a.risk)}</p><p><b>Horizon</b> ${esc(a.horizon)}</p><p><b>Watch next</b> ${esc(a.watch)}</p><div class="daily-sources">${a.sources.map((u,i)=>researchLink(u,'Source '+(i+1))).join(' · ')}</div><small class="muted">poor research · testable hypothesis, not a proven trading edge</small></article>`).join('')}</div></section>`).join('')||'<p class="empty">No connection has passed the research checks yet. Briefs require distinct evidence, a catalyst, market context and a testable thesis.</p>'}
async function loadDailyResearch(){if(dailyBusy)return;dailyBusy=true;try{const r=await getLiveJSON('/api/research/daily');$('#dailyArticles').innerHTML=dailyArticlesHTML(r.editions||[]);const overdue=r.lastAttempt&&Date.now()-Date.parse(r.lastAttempt)>36*3600000;$('#dailyStatus').textContent=(overdue?'Research overdue · ':'')+(r.status||'Daily research')+(r.lastAttempt?' · Checked '+stamp(r.lastAttempt):'')+' · Daily, 08:00 Paris'}catch{$('#dailyStatus').textContent='Daily research unavailable; retry shortly. Previously loaded briefs remain visible.'}finally{dailyBusy=false}}
if(typeof window!=='undefined'){$('#dailyRefresh').onclick=loadDailyResearch;setInterval(()=>{if(!document.hidden&&view==='daily')loadDailyResearch()},15*60000)}
